#include "engine/plugins/IPluginPermissions.hpp"
#include <algorithm>
#include <map>
namespace engine::plugins { namespace { class Policy final:public IPluginPermissionPolicy { std::map<std::string,std::vector<std::string>> grants_; public: PermissionDecision evaluate(const std::string&p,const std::string&n)const override{auto i=grants_.find(n);if(i!=grants_.end())for(const auto&x:i->second)if(x==p)return{p,true,"granted"};return{p,false,"permission_denied"};}std::vector<PermissionDecision>evaluate_all(const std::string&n,const std::vector<std::string>&ps)const override{std::vector<PermissionDecision>o;for(const auto&p:ps)o.push_back(evaluate(p,n));return o;}bool grant(const std::string&p,const std::string&n)override{if(p.empty()||n.empty())return false;auto&v=grants_[n];for(const auto&x:v)if(x==p)return false;v.push_back(p);return true;}bool revoke(const std::string&p,const std::string&n)override{auto i=grants_.find(n);if(i==grants_.end())return false;auto j=std::find(i->second.begin(),i->second.end(),p);if(j==i->second.end())return false;i->second.erase(j);return true;}bool is_granted(const std::string&p,const std::string&n)const override{return evaluate(p,n).allowed;}}; } std::unique_ptr<IPluginPermissionPolicy>create_plugin_permission_policy(){return std::make_unique<Policy>();}}
